#!/usr/bin/env python3
# THE DEUTERONOMY WALK sitting 12 — CHAPTER 14 (2026-09-21, the one run and its tail): THE CLAIMS of Deuteronomy 14:1-29, ONE manifest for the one draft unit, read off
# this sitting's ledger, every claim LABELED (logic/MIDDOT.md's codes; World/step9/CLAIM_LABELS.md), a machine check where the ink allows —
# every he_contains substring CUT FROM THE SNAPSHOT STORE'S OWN BYTES by the word's CONSONANTS: the check is the word's LONGEST PIECE WHOLE
# (never a prefix fragment; the floor four code points). Claim IDs DV14- (14:1-29). Written once (no file may exist; the ID prefix checked absent from
# every existing manifest and unit). Every source cite is checked against the ledger's CITE INDEX before a byte is written, and every CITE INDEX name
# must be used by a claim — the spine's 111 rows distributed by piska over the claims whose verses they head (piska 96's tail 9-12 with the children and
# the cuts; the three outside rows with the claims whose verses they cite). Sitting 11's form (write_ch13_manifest.py). RUN FROM THE REPO ROOT.
import json, os, re, sqlite3, glob, subprocess
ROOT = _ROOT
DATE = '2026-09-21'
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth, (book, ch, v, word, hit)
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    assert len(piece) >= 4, (book, ch, v, word, he.split('/'))
    return idx, piece
def hc(ref, word, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    idx, sub = cut(b, c, v, word, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
def onk(c, lo, hi): return '; '.join(f'Onkelos Deut {c}:{v}' for v in range(lo, hi + 1))
def sif(*rows): return '; '.join(f'Sifrei Devarim {r}' for r in rows)
led = open(f'{ROOT}/logic/oral_triage/deu_14_reeh_{DATE}.md', encoding='utf-8').read().split('## CITE INDEX')[1]
CI = set(re.findall(r'^(Onkelos Deut \d+:\d+|Sifrei Devarim \d+:\d+)$', led, re.M))
assert len(CI) == 143, len(CI)
SIF = sorted((int(a), int(b)) for a, b in (s.split(' ')[2].split(':') for s in CI if s.startswith('Sifrei')))
def sifp(*ps): return '; '.join(f'Sifrei Devarim {p}:{r}' for p, r in SIF if p in ps)   # every row of the piskaot named, from the CITE INDEX itself
def sifr(p, lo, hi): return '; '.join(f'Sifrei Devarim {q}:{r}' for q, r in SIF if q == p and lo <= r <= hi)   # a piska's rows by range (96's tail 9-12)
assert len(SIF) == 114 and sum(1 for p, _ in SIF if 96 <= p <= 110) == 111, (len(SIF), sum(1 for p, _ in SIF if 96 <= p <= 110))
assert sifr(96, 9, 12).count(';') == 3 and not sifr(96, 1, 8), 'piska 96: rows 9-12 the chapter\'s, 1-8 chapter 13\'s'

